"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4540],{4540:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/3fdf128ee9e00ced9bce2f39d65309b4.jpg\\"\\n  title=\\"Little Crumb Bakery\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"Shop 1/57 Great Ocean Rd, Apollo Bay VIC 3233 Australia\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nA stop for lunch during the <mark>Great Ocean Road</mark> tour.  \\nThe guide had a separate restaurant recommendation, but I was in the mood for something breakfast-like, so I found this place myself.\\n\\nThe eggs were fluffy and soft — really good.  \\nThe <mark>croissant</mark> was surprisingly much better than expected.\\n```adcard\\n```\\nPlenty of locals were dropping by for takeout lunch, and the tables inside were all full.  \\nIt was quite cold that day, which somehow made the coffee taste even better.\\n\\nLocated right in front of Apollo Bay beach, it\'s known for its artisan croissants and specialty coffee.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/3fdf128ee9e00ced9bce2f39d65309b4.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little Crumb Bakery\\">\\n<img src=\\"/assets/snippets/location/7cf37400204a9b7c83e68e86c799a437.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little Crumb Bakery\\">\\n<img src=\\"/assets/snippets/location/c5588686265d4ff86a71b4428cb8c24a.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little Crumb Bakery\\">\\n<img src=\\"/assets/snippets/location/499938d56e84aa9e1f0bf7ff8d0055fc.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Little Crumb Bakery\\">\\n</pictures>\\n"}')}}]);